const SUPABASE_URL = 'https://lgdgbrivnhgeupqhkckd.supabase.co';
const SERVICE_ROLE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const ANTHROPIC_API_KEY = $env.ANTHROPIC_API_KEY;
const RESEND_API_KEY = $env.RESEND_API_KEY;

const { etape, jours_silence, campagne } = $input.first().json;

// ── 1. Récupérer les testeurs éligibles à cette étape ──────────────────
const rpcRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/rpc/get_testeurs_reveil`,
  headers: {
    apikey: SERVICE_ROLE_KEY,
    Authorization: `Bearer ${SERVICE_ROLE_KEY}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({ p_jours_silence: jours_silence, p_campagne: campagne, p_etape: etape }),
  json: true,
});

const testeurs = Array.isArray(rpcRes) ? rpcRes : [];
if (testeurs.length === 0) {
  return [{ json: { message: 'Aucun testeur éligible pour cette étape', etape, envoyes: 0 } }];
}

// ── 2. Contexte par étape (angle de la relance) ─────────────────────────
const ANGLES = {
  1: "Objectif : réchauffement doux. Rappelle-lui concrètement ce qu'on a fait ensemble (utilise la mémoire fournie si elle existe, sinon reste général sur son activité). Mentionne une nouveauté utile livrée récemment dans Assists (notifications de commande instantanées, suivi client). Invite-le simplement à revenir jeter un oeil. Ton personnel, pas commercial.",
  2: "Objectif : preuve concrète. Donne un exemple réel et court de ce qu'Assists permet de faire pour un entrepreneur comme lui (mets en avant une action précise adaptée à son profil : clarté si perdu, structuration si désorganisé, automatisation si non scalé). CTA clair vers son lien personnel.",
  3: "Objectif : dernier rappel avant qu'on referme l'accès prioritaire des tout premiers testeurs. Ton direct, honnête, sans pression artificielle ni fausse urgence. Une seule question simple : est-ce qu'il veut continuer avec Assists ou non.",
};

const results = [];

for (const t of testeurs) {
  const lienPerso = 'https://assists.agenceattractor.com';
  const contexteMemoire = t.memoire_cache ? `Ce qu'on a fait ensemble : ${t.memoire_cache}` : "Pas d'historique détaillé disponible — reste général sur son activité.";

  const systemPrompt = `Tu écris au nom de Mac Arthur (Mr Attractor), fondateur d'Attractor Assists, un email court à un testeur gratuit qui n'a plus ouvert l'app depuis un moment.
Règles strictes : français, tutoiement, direct et chaleureux, zéro emoji, zéro markdown (pas de **gras**, pas de listes à puces), zéro flagornerie, zéro exclamation en excès. Une seule idée par email, 80 à 120 mots maximum. Signature simple "Mac Arthur" à la fin, pas de bloc de signature formel.
Termine toujours par une phrase du type "Réponds STOP si tu ne veux plus recevoir ces messages."
Renvoie UNIQUEMENT un JSON strict de la forme {"objet": "...", "corps": "..."} — le corps en texte brut avec des retours à la ligne \n, sans HTML.

${ANGLES[etape] || ANGLES[1]}`;

  const userPrompt = `Prénom : ${t.prenom || 'là'}\nActivité : ${t.activite || 'non précisée'}\nProfil : ${t.profil_type || 'non détecté'}\nDernière connexion : ${t.last_seen || 'jamais revenu depuis l\'inscription'}\n${contexteMemoire}\nLien personnel à inclure : ${lienPerso}`;

  let objet = 'Des nouvelles d\'Attractor Assists';
  let corps = null;
  try {
    const claudeRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: {
        'x-api-key': ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 400,
        system: systemPrompt,
        messages: [{ role: 'user', content: userPrompt }],
      }),
      json: true,
    });
    const raw = claudeRes?.content?.[0]?.text?.trim() || '{}';
    const parsed = JSON.parse(raw.replace(/^```json\n?/, '').replace(/```$/, ''));
    objet = parsed.objet || objet;
    corps = parsed.corps || null;
  } catch (e) {
    results.push({ user_id: t.user_id, email: t.email, ok: false, step: 'claude', error: e.message });
    continue;
  }

  if (!corps) {
    results.push({ user_id: t.user_id, email: t.email, ok: false, step: 'claude_empty' });
    continue;
  }

  const htmlBody = corps.split('\n').map(l => l ? `<p style=\"margin:0 0 12px;font-family:sans-serif;color:#1A1714;font-size:15px;line-height:1.5\">${l}</p>` : '').join('');

  // ── 3. Envoi via Resend ────────────────────────────────────────────
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.resend.com/emails',
      headers: {
        Authorization: `Bearer ${RESEND_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: 'Mac Arthur <noreply@agenceattractor.com>',
        to: t.email,
        subject: objet,
        html: htmlBody,
      }),
      json: true,
    });
  } catch (e) {
    results.push({ user_id: t.user_id, email: t.email, ok: false, step: 'resend', error: e.message });
    continue;
  }

  // ── 4. Log anti-doublon ────────────────────────────────────────────
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/campagne_envois`,
      headers: {
        apikey: SERVICE_ROLE_KEY,
        Authorization: `Bearer ${SERVICE_ROLE_KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal',
      },
      body: JSON.stringify({ user_id: t.user_id, campagne, etape }),
      json: true,
    });
  } catch (e) { /* non-bloquant : au pire un doublon possible au prochain run */ }

  results.push({ user_id: t.user_id, email: t.email, ok: true, objet });

  // Petite pause pour rester raisonnable sur les rate limits Resend/Anthropic
  await new Promise(r => setTimeout(r, 600));
}

return [{ json: { etape, total: testeurs.length, envoyes: results.filter(r => r.ok).length, echecs: results.filter(r => !r.ok), details: results } }];
